const LING = ["47natcha@gmail.com", "arandatrad@gmail.com", "austra.muizniece@gmail.com", "boh.vozniuk@gmail.com", "bruno@bsttranslations.com", "daniel@dgmultilingualservices.com", "dmluciahorea@gmail.com", "ellen.de.venter@outlook.com", "farahputri@gmail.com", "futuremedia@sdl.com", "harald.roald@gmail.com", "ilaria.roncaglia@gmail.com", "ivanaturcin@ymail.com", "jaromirvicari@me.com", "julius.valkiunas@gmail.com", "karahansisman@gmail.com", "katri.varvikko@gmail.com", "kenneth@phraseit.dk", "marit.teichmann@gmail.com", "michal.tosza@translators.org.pl", "mjlocalize@gmail.com", "mteixeira@sacradomus.com", "mteres@terestraducciones.com", "nerissaneptuno@gmail.com", "qrcodelocalization@gmail.com", "quentinnguyen.localize@gmail.com", "root-translations@outlook.com", "roxanamoldovan25@gmail.com", "ruckova.lucia@gmail.com", "sabrathan@gmail.com", "sara.guinot.trad@gmail.com", "silis.martins@gmail.com", "silke.luehrmann@gmx.de", "straus.translations@gmail.com", "therese.svardsten@gmail.com", "translation@cornell.hu", "vidiasc@gmail.com"];
const NAMES = { es: 'Spanish (Spain)', fr: 'French', it: 'Italian', pt: 'Portuguese (Brazil)', ro: 'Romanian', pl: 'Polish', lt: 'Lithuanian', lv: 'Latvian' };
const EXTRA = { lt: 'The reader is addressed with formal "Jūs": use feminine SINGULAR agreement (e.g. "Jūs esate pasirengusi", "jaučiatės atsakinga"), never masculine plural.', lv: 'The reader is addressed with formal "Jūs": use feminine SINGULAR agreement (e.g. "Jūs esat pieradusi", "jūtaties atbildīga"), never masculine plural.', fr: 'Never use dual forms like "(e)". The reader may be addressed as "vous": still use feminine singular agreement ("vous êtes prête").', pl: 'Use feminine forms for the reader/speaker: adjectives (-a), past tense (-łaś, -łam), conditional (-łabyś), "sama", instrumental "-ą".', es: '', it: '', pt: '', ro: '' };
const all = []; for (const it of $input.all()) { if (!Array.isArray(it.json.keys)) throw new Error('no keys'); all.push(...it.json.keys); }
const out = [];
for (const iso of Object.keys(NAMES)) {
  const items = [];
  for (const k of all) { const en = (k.translations||[]).find(t => t.language_iso === 'en'); const tr = (k.translations||[]).find(t => t.language_iso === iso);
    if (!tr || !tr.translation || typeof tr.translation !== 'string') continue; if (LING.includes(tr.modified_by_email)) continue;
    items.push({ i: tr.translation_id, en: en ? en.translation : '', t: tr.translation }); }
  for (let j = 0; j < items.length; j += 20) {
    const chunk = items.slice(j, j + 20);
    const sys = 'You are a meticulous native ' + NAMES[iso] + ' editor. The strings come from the results profile of a personality test that is ONLY for women (Female Archetype). The reader ("you") is always a woman, and when the text speaks in first person ("I") the speaker is always a woman. Your ONLY job: make every word that refers to the reader or to the speaker grammatically FEMININE (adjectives, participles, past-tense verb endings, reflexive/emphatic pronouns such as "yourself", and nouns or pronouns designating her, e.g. "someone who", "the one who"). Change NOTHING else: keep the wording, word order, punctuation, spacing (including non-breaking spaces), quotes, placeholders like [%1$s:x] or {{x}}, and HTML exactly as they are. Words that agree with other nouns (things, other people, groups) must stay as they are. Statements about other people stay unchanged. If a string is already correct, return it unchanged. ' + EXTRA[iso] + ' Reply with JSON only: {"items":[{"i":<id>,"t":"<string>"}]} containing every input item, in the same order.';
    out.push({ json: { iso, n: chunk.length, body: { model: 'gpt-4.1', temperature: 0, response_format: { type: 'json_object' }, messages: [ { role: 'system', content: sys }, { role: 'user', content: JSON.stringify({ items: chunk.map(c => ({ i: c.i, en: c.en, t: c.t })) }) } ] }, src: chunk } });
  }
}
return out;

const reqs = $('Build batches').all(); const res = $input.all(); const rows = []; const errs = [];
res.forEach((it, i) => { const r = reqs[i].json; let parsed = null;
  try { parsed = JSON.parse(it.json.choices[0].message.content); } catch (e) { errs.push({ iso: r.iso, i, e: String(e).slice(0,200), b: JSON.stringify(it.json).slice(0,300) }); return; }
  const m = {}; for (const x of (parsed.items||[])) m[String(x.i)] = x.t;
  for (const s of r.src) { const nt = m[String(s.i)]; if (typeof nt !== 'string') { errs.push({ iso: r.iso, missing: s.i }); continue; } if (nt !== s.t) rows.push({ iso: r.iso, tid: s.i, en: s.en, old: s.t, new: nt }); } });
return [{ json: { n: rows.length, errs, rows } }];
